Denote failure probability $\delta \in (0, 0.1)$. Define $B := \max\{O(\sqrt{\log(Nmd/\delta)}), 1\}$. Assuming there exists a constant $R \in (0, 1)$ satisfying $\| w_{(\nu), r}(t) - w_{(\nu), r}(0) \|_2 \leq R$ and $\| U_{(\nu)}(t) - U_{(\nu)}(0)\|_F \leq R$ for $r \in [m]$ and $\nu \in [N]$ and $R \in (0, 1)$.

    We mark the indices as: $r\in [m]$, $p \in [nL]$, $\ell_1, \ell_2 \in [L]$, and $\nu \in [N]$. We denote $i = \lfloor p / L \rfloor$, $\ell = p {\rm ~ mod~} L$, $\ell' \in [\ell]$.

    If Definition~5.2 holds, then with a probability at least $1 - \delta$, we have:
    \begin{itemize}
        \item {\rm Basic Bounds.}
        \begin{itemize}
            \item {\bf Part 1.} $\| w_{(\nu), r}(0) \|_2 \leq O(\sqrt{d}B)$.
            \item {\bf Part 2.} $\| U_{(\nu)}(0) \|_F \leq O(dB)$.
            \item {\bf Part 3.} $\| w_{(\nu), r}(t) \|_2 \leq O(\sqrt{d}B)$.
            \item {\bf Part 4.} $\| U_{(\nu)}(t) \|_F \leq O(dB)$.
            \item {\bf Part 5.} $\| \Lambda_{(\nu), i, \ell}(t) \|_2 = \Theta(1)$ for all $\ell \in [L]$.
            \item {\bf Part 6.} $\| \Lambda_{(\nu), i}(t) U_{(\nu)}(t) \Lambda_{(\nu), i}(t)^\top \|_\infty \leq O(dB)$.
            \item {\bf Part 7.} $ \exp\big( [\Lambda_{(\nu), i}(t) U_{(\nu)}(t) \Lambda_{(\nu), i}(t)^\top]_{\ell_1, \ell_2} \big) \in [ \exp(-O(dB)), \exp(O(dB)) ]$ for all $\ell_1, \ell_2 \in [L]$.
            \item {\bf Part 8.} For  $\ell'\in [\ell]$, $ \sigma_{(\nu), p, \ell'}(t) \in [\exp(-O(dB)) / L, 1]$.
        \end{itemize}
        \item {\rm Perturbation Bounds.}
        \begin{itemize}
            \item {\bf Part 9.} $\| w_{(\nu), r}(t) - w_{(\nu), r}(0) \|_2 \leq R$.
            \item {\bf Part 10.} $\| U_{(\nu)}(t) - U_{(\nu)}(0)\|_F \leq R$.
            \item {\bf Part 11.} $\| \Lambda_{(\nu), i, \ell}(t) - \Lambda_{(\nu), i, \ell}(0)\|_2 \leq O(R)$.
            \item {\bf Part 12.} $\| \sigma_{(\nu), p}(t) - \sigma_{(\nu), p}(0) \|_2 \leq O(\sqrt{L}R)$.
            \item {\bf Part 13.} $\| o_{(\nu), p}(t) - o_{(\nu), p}(0) \|_2 \leq O(\sqrt{L}R)$.
        \end{itemize}
        \item {\rm Gradient and Function Norms.}
        \begin{itemize}
            \item {\bf Part 14.} ${\cal L}(t, \mathbb{D}) \leq O(Ld)$.
            \item {\bf Part 15.} $\| \frac{\mathrm{d} {\cal L}(t, \mathbb{D})}{\mathrm{d} \mu_{(\nu)}(t)} \|_F^2 \asymp \frac{\varepsilon^2}{n} \cdot {\cal L}(t, \mathbb{D})$. {\it (Note: the $1/n$ factor is essential and traces directly to the $\frac{1}{n}$ in the loss definition $\mathcal{L} = \frac{1}{n}\|\mathsf{F}-\mathsf{Y}\|_F^2$. See proof below.)}
            \item {\bf Part 16.} $\| \gamma_{(\nu), p}(t) \|_2 \leq o(1/\sqrt{m})$.
        \end{itemize}
    \end{itemize}

