Assuming Assumption~5.1 and Definition~5.2 hold, denote the failure probability $\delta \in (0, 0.1)$, then the kernel perturbation bound is:
    \begin{align*}
        \Pr\left[\lambda_{\min}(H_{(\nu)}(t)) < \omega\lambda  /2\right] < \delta.
    \end{align*}
    Therefore, bounding loss dynamics is given by ($C > 0$ is an absolute constant):
    \begin{align*}
        \Pr\left[{\mathbb{E}}\!\left[\frac{\mathrm{d} }{\mathrm{d} t}{\cal L}(t, \mathbb{D})\right] > - \frac{C \cdot \omega\lambda N \cdot \varepsilon^2}{n} \cdot {\cal L}(t, \mathbb{D})\right] < \delta.
    \end{align*}
    {\it (The $\varepsilon^2/n$ factor appears explicitly: $\varepsilon^2$ comes from Part~15 of Lemma~G.1, and the $1/n$ factor is the $1/n$ in $\mathcal{L} = \frac{1}{n}\|\mathsf{F}-\mathsf{Y}\|_F^2$. We track this $1/n$ explicitly because it propagates downstream into the phase-boundary exponent of Theorem~J.7.)}

Assuming Assumption~5.1, Definition~5.4 and Definition~5.2 hold, denote the failure probability $\delta \in (0, 0.1)$, then with a probability at least $ 1 - \delta$, we have:
    \begin{itemize}
        \item {\bf ($n, |\mathbb{B}|$)-Fixed Convergence.} Let $\alpha := C\cdot \omega\lambda N$ where $C>0$ is an absolute constant and $\omega N = \Theta(1/(L^2 d^{2.5}B^3))$ is a function of architecture only (Definition~5.2). Then:
        \begin{align*}
            {\cal L}({\sf T}, \mathbb{D}) \leq \exp\!\left(- \alpha \cdot \frac{\varepsilon^2  T}{\mathsf{N}}\right) \cdot {\cal L}(0, \mathbb{D}).
        \end{align*}
        Equivalently, writing $\bar\alpha := C\cdot\lambda$ (treating $L,d,B$ as fixed architectural constants and absorbing the polynomial $\omega N = \mathrm{poly}(1/L,1/d,1/B)$ into $\bar\alpha = \mathrm{poly}(L,d,B,\lambda)$), we have ${\cal L}({\sf T}, \mathbb{D}) \leq \exp(-\bar\alpha\,\varepsilon^2 T/\mathsf{N})\cdot {\cal L}(0,\mathbb{D})$.
    \end{itemize}

Assuming we have arbitrary dataset size ${\sf N} \in (0, +\infty)$. Let all scaling law factors be defined as Definition~5.4 and Assumption~5.1 and Definition~5.2 hold. Denote the failure probability $\delta \in (0, 0.1)$. For the Good Model Class $ {\cal F}_{\sf M, T, N}(\mathbb{D})$ with training dataset $\mathbb{D}$ and target function $F^*: {\cal X} \to {\cal Y}$, we choose $\varepsilon \lesssim {\sf M}^{-1}$, with a probability at least $1 - \delta$, we have:
    \begin{align*}
        & ~ \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} {\mathbb{E}}_{(X, Y) \sim \mathcal{D}}[ \| F(X) - F^*(X)\|_F^2 ] \le {\sf M}^{-2}.
    \end{align*}

Let all pre-conditions hold as Corollary~I.4 and choose $\varepsilon = \Theta(1/{\sf M})$. Then, with a probability at least $1 - \delta$, there exists:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}} \Delta{\cal R}(F) \leq \big(4{\sf M}^{-1} + Ld\cdot \xi\big) \cdot {\sf M}^{-1} + \frac{Ld \cdot\xi^2}{\sf N}.
    \end{align*}
    We retain the $Ld$ factors explicitly in both terms because $L$ (sequence length) and $d$ (embedding dimension) are scaling-law variables independent of the noise level $\xi$.

Let $K$ be the layer-aggregated NTK at initialization, $K(x,y):=\sum_{\nu\in[N]}H_{(\nu),x,y}(0)$, and $\mathcal{H}_K$ its associated RKHS. Suppose there exists a non-zero element $g\in {\cal H}_K$ with $\|g\|_{L^F({\cal X})}>0$. Assume the noise $\Xi$ has each token-coordinate $\Xi_{\ell, k}$ Gaussian with variance $\xi^2$ (the standard sub-Gaussian assumption strengthens this to a constant factor; see Remark~J.10). Let $\widehat F := \widehat F(\mathbb{D})$ denote any (deterministic or randomized) measurable estimator of $F^*$ from a dataset $\mathbb{D}$ of size $\sf N$. Then there exist absolute constants $c_1, c_2>0$ such that:
    \begin{align*}
        \inf_{\widehat F} \sup_{F^*\in {\cal H}_K} {\mathbb{E}}_{\mathbb{D}\sim {\cal D}^{\otimes {\sf N}}}\big[\Delta{\cal R}(\widehat F)\big] \ge c_1 \cdot \frac{\xi^2}{{\sf N}}.
    \end{align*}

Let all pre-conditions hold as Corollary~I.4 and choose $\varepsilon = \Theta(\xi/{\sf N})$. Then, with a probability at least $1 - \delta$, the following condition divides the scaling trend into two stages:
    \begin{align}
        {\sf C} > \frac{{\sf N}^7\log( {\sf N}  \cdot Ld/\xi^2)}{\xi^2}.
    \end{align}
    \begin{itemize}
        \item {\it Stage I (Compute-Starved Stage).} If Equation~(18) does not hold, then there exist constants $\alpha,C,c_2',C_{\rm opt}'>0$ depending polynomially on $(L,d,1/\lambda,1/\omega)$ such that:
        \begin{align*}
            c_2'\,\exp\!\big(-C_{\rm opt}'\, \kappa_{\sf opt}\cdot \xi^2{\sf C}/{\sf N}^7\big)\cdot{\cal L}(0,\mathbb{D}) \;\le\;
            \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)
            \;\le\; C \exp\!\big(-\alpha\, \xi^2{\sf C}/{\sf N}^7\big) \cdot {\cal L}(0, \mathbb{D}),
        \end{align*}
        where $\kappa_{\sf opt}\in[\sqrt{\lambda/\lambda_{\max}},\,1]$ is a square-root-condition-number factor that distinguishes the upper from the lower bound (see Theorem~J.12 and Remark~J.13).
        \item {\it Stage II (Data-Limited Stage).} If Equation~(18) holds, then there exists $c_1'>0$ such that:
        \begin{align*}
            c_1'\cdot \xi^{12/7}\cdot \widetilde\Omega\!\big({\sf C}^{-1/7}\big)
            \;\le\;
            \inf_{F\in{\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)
            \;\le\;
            \xi^{12/7} \cdot O\!\Big( \frac{{\sf C}}{W({\sf C}/\xi^{12})} \Big)^{-1/7} \le \xi^{12/7} \cdot \widetilde{O}\!\big({\sf C}^{-1/7}\big),
        \end{align*}
        where $W(\cdot)$ is the Lambert $W$ function and $\widetilde O,\widetilde \Omega$ hide $\log {\sf C}$ factors.
    \end{itemize}
    The upper bounds follow from the analysis below; the lower bounds follow from Corollary~J.11 (statistical) and Theorem~J.12 (optimization-side). The boundary $\mathsf{N}^7$ and Stage~II rate $\xi^{12/7}\mathsf{C}^{-1/7}$ both arise from the $1/\mathsf{N}$ factor in the convergence rate (Remark~I.3) that the average-loss normalization contributes; the Pythia compute-frontier exponent $\eta=0.120$ in Appendix~D.3 is in the same range as the theoretical $1/7\approx 0.143$.

Under Assumption~5.1 and Definition~5.2, denote $\lambda_{\max}:= \max_{\nu\in[N]} \lambda_{\max}(H_{(\nu)}'(0)/\omega)$. There exist absolute constants $c_2, C_{\rm opt}>0$ such that for any first-order method ${\cal A}$ and any time horizon ${\sf T}\ge 0$, there exists a data distribution ${\cal D}$ and an initialization $\theta(0)$ for which:
    \begin{align*}
        {\cal L}({\sf T}, \mathbb{D}) \ge c_2\cdot \exp(-C_{\rm opt}\cdot \omega\lambda_{\max}\cdot \varepsilon^2 \cdot {\sf T}) \cdot {\cal L}(0, \mathbb{D}).
    \end{align*}
    Combined with the compute identity ${\sf C} = O({\sf MTN})$, ${\sf M}=\Theta({\sf N}^3)$, $\varepsilon = \xi/{\sf N}$, and the $1/\mathsf{N}$ factor in the rate (Remark~I.3), this yields a lower bound on the excess risk in the {\it Compute-Starved Stage}:
    \begin{align*}
        \inf_{F\in{\cal F}_{\sf M, T, N}(\mathbb{D})}\sup_{\mathbb{D}\in{\cal D}} \Delta{\cal R}(F) \ge c_2'\cdot \exp(-C_{\rm opt}'\cdot \sqrt{\kappa}\,\xi^2{\sf C}/{\sf N}^7) \cdot {\cal L}(0, \mathbb{D}),
    \end{align*}
    matching the upper bound of Theorem~J.7 up to a $\sqrt{\kappa}$ factor in the exponent (where $\kappa:=\lambda_{\max}/\lambda$); the $\sqrt{\kappa}$ gap reflects the difference between the spectral lower bound used in the upper-bound argument and the geometric-mean rate produced by the Nemirovski--Yudin lower bound, and is unavoidable for first-order methods.
